d=dict(paper_id=2,title_match=True,reviewed_pages=list(range(1,39)),scope_note='阅读全文含技术附录。旧表仅一个综合指标，实际有目标意象选择、消费者评分、专家多准则评估等14个可区分评价环节；不同样本不假定独立，不加总为唯一参与者人数。',domain_codes=['D2'],stage_codes=['S1','S2','S3'],ai_function_codes=['F1','F3','F4','F6'],ai_role_codes=['R1','R2'],target_user_codes=['U1'],context_summary='GPT-5分析评论引出科技/运动意象；Midjourney生成电摩形态，人工评价与形态组合；Stable Diffusion和qwen-image-edit生成配色材质后评价筛选。评价用于设计迭代和方法案例验证。',context_evidence=[quote(15,'twelve transportation-design professionals rated the GPT-5 outputs on a 0–1 scale'),quote(14,'This iterative ‘evaluation–feedback–regeneration’ loop ensures the iterability and collaborative nature'),quote(20,'we conducted a consumer Kansei questionnaire and an AHP-based designer evaluation')],evaluations=[],excluded_legacy_rows=[],added_evidence_notes='补录旧表遗漏的美观、人体工学/尺度、制造可行与可替换性评价及多次数据采集。第20/22/26/28页称0–1量尺，但表8/10/14/16显示约50–80，缩放解释缺失。第28页运动配色两排名并非全一致（2与4、1与8、6与7等）。',category_gaps=['原始感性意象（technological/sporty）按E2目标意象匹配编码；不把technological一词本身当作客观技术质量。'])
