def ev(i,n,pages,task,criteria,result,who='V3',purpose=None,tool='M1',reliability='NR',reliability_facts='完整阅读方法、结果与附录；该环节未报告一致性或复测依据。',design='G2',origin='T3',construct='Kansei imagery match',ind='E2',dim='E',legacy=None,scale='0–1连续评分；取均值；锚点文字NR',a6='S',a6reason='限定于候选方案在本样本中的描述性选择；未进行总体差异或因果推断。',a7='S',a7reason='目标意象与所报评分/排序对应，结论限定于候选方案。',a2='S',a2reason='给出目标意象与直接判断题，且目标消费者参与；作为语义匹配判断有明确内容依据。',claim=None):
 q=criteria
 e=dict(eval_id=f'002-E{i}',legacy_eval_ids=['2-评价1'] if legacy else [],purpose_codes=purpose or ['P3'],object_codes=['O7'] if i==1 else ['O1'],evaluator_codes=[who],source_codes=['H1','H2'],setting_code='NR',design_code=design,evaluation_stage_codes=['S1'] if i==1 else ['S3'],sample_n=n,sample_description=task,recruitment='NR；未报告具体招募渠道和跨环节参与者是否重叠',task=task,comparator='同批多意象/多候选方案；无传统设计工作流对照',procedure=criteria+'；'+scale,analysis='候选均值和排名' if tool=='M1' else '感性工学多准则决策；详见构念链',actual_results=result,limitations=lim,ethics='NR；正文及附录未报告伦理审批或知情同意',evidence=[dict(field='procedure',page=pages[0],quote=q),dict(field='result',page=pages[-1],quote=result)],audit=[audit('U5','S','说明引出/选择与目标意象相符的方案。','采集内容直接服务该设计决策。',pages,q),audit('A2',a2,criteria,a2reason,pages,q),audit('A3',reliability,reliability_facts,'AHP一致性不等于跨评价者可靠性；alpha若未说明计算单位，只作部分依据。' if reliability=='P' else '未以未报告推定实际不可靠；只能判断支持信息不足。',pages,reliability_facts if reliability!='NR' else q),audit('A4','P',task,'报告人数、部分年龄/性别和刺激；招募、实施环境、展示顺序与跨环节重叠不足。',pages,q),audit('A6',a6,'报告描述统计/多准则算法和结果。',a6reason,pages,result),audit('A7',a7,'结论按候选评价结果筛选方案。',a7reason,pages,result),audit('E1','P','题意、量尺、刺激与汇总结果可见。','个体数据和部分过程/量尺缩放交代不足；数据可按需索取。',pages,q)],chains=[])
 c=chain(legacy or [],claim or result,'按目标意象选择候选方案',construct,criteria,dim,ind,result,pages,instrument_raw='自编感性评分问卷' if tool=='M1' else '感性问卷结合'+tool,tool_family_codes=[tool],tool_origin_code=origin,response_scoring=scale,validity_evidence=criteria,reliability_evidence=reliability_facts,claim_type='C4' if i==1 else 'C2',effect_direction='候选方案排序',adaptation='NR；非具名心理量表')
 e['chains']=[c]; d['evaluations'].append(e); return e

