def experts(i,page,note,res,style):
 e=ev(i,20,[page,page+1],note,f'Does the shape exhibit a {style} aesthetic?; Does the shape possess aesthetic appeal?; Is the seating ergonomically designed?; Are the dimensions reasonable?; Is the shape conducive to manufacturing and processing?; Are the shape components easily replaceable?',res,who='V1',tool='M6',a2='P',a2reason='题意明确；渲染外形不足以验证真实人体工学和制造性质，结果仅作专家感知判断。',a6='P',a6reason='报告GRA步骤与汇总表，但表中灰关联值大于1，与文中平均系数定义范围不符，需作者澄清；不重算为客观真值。')
 base=e['chains'][0]
 base['instrument_raw']='0–1专家评分＋Grey Relational Analysis (GRA)'; base['response_scoring']='六准则评分均值，灰关联选择前四外形'
 vals=[('Kansei match','E','E2',f'Does the shape exhibit a {style} aesthetic?'),('Aesthetic appeal','A','A2','Does the shape possess aesthetic appeal?'),('Ergonomics and dimensions','A','A3','Is the seating ergonomically designed?; Are the dimensions reasonable?'),('Manufacturing and replaceability','A','A4','Is the shape conducive to manufacturing and processing?; Are the shape components easily replaceable?')]
 e['chains']=[dict(base,construct_raw=v[0],indicator_raw=v[0],dimension_code=v[1],indicator_code=v[2],item_quote=v[3]) for v in vals]
 return e
